# -*- coding: utf-8 -*-
"""Phase 09: 실수의 완비 (weeks 105–117)."""
from curriculum.common import phase
from curriculum.ma.resources import R9

PHASE = phase("실수의 완비", 105, 117, "점화", "완비", "유리수의 빈틈에서 출발해 상한 공리, 단조수렴 정리, 코시 수열을 증명한다.", R9, [
("유리수의 빈틈", "제곱", "무리수", "제곱해 2가 되는 유리수는 존재하지 않는다. 따라서 수직선을 유리수만으로 채우면 빈틈이 남는다.", "p/q가 기약분수이고 p^2=2q^2이면 p는 짝수다. p=2k를 대입하면 q도 짝수가 되어 기약분수라는 가정과 모순된다.", "1.414를 제곱이 정확히 2인 유리수라고 착각하기 쉽지만, 유한소수는 유리수일 뿐 그 제곱은 2와 미세하게 다르다.", "제곱이 2인 유리수가 없다는 증명을 기약분수 조건부터 백지에 다시 쓴다.", "분자와 분모가 모두 짝수가 되어 기약분수 가정이 깨지는 지점이 귀류법의 핵심이다.", "제곱이 2인 유리수가 없음을 백지에 증명하고, 1.414^2이 2가 아님을 직접 계산해 보인다."),
("상한", "최소", "윗경계", "집합이 위로 유계면 윗경계 중 가장 작은 수를 상한이라고 한다. 실수의 완비는 공집합이 아닌 위로 유계인 집합마다 상한이 있다는 말이다.", "S={x 유리수: x^2<2}의 윗경계는 2, 3, ... 이고 상한은 제곱근 2다. 그 상한은 S 안에 없다.", "윗경계 하나를 상한이라고 부르면 2와 3이 둘 다 상한이 되어 최소가 사라진다.", "유한 집합 3개의 상한을 구하고, 열린구간 (0,1)의 상한이 1이며 1은 원소가 아님을 말한다.", "상한은 집합의 원소일 필요가 없다. 원소 중 최댓값과 다르다.", "(0,1)의 상한이 1인 이유와 1이 원소가 아닌 이유를 두 문장으로 말한다."),
("아르키메데스", "자연수", "넘기", "어떤 양수보다 큰 자연수가 있다. 따라서 양수 엡실론마다 1/n이 그보다 작아지는 n이 있다.", "0.1보다 작은 1/n은 n>10. 자연수 11이면 된다.", "가장 큰 자연수가 있다고 하면 거기에 1을 더해 아르키메데스가 깨진다.", "엡실론 0.1, 0.01, 0.001에 대해 1/n이 그보다 작아지는 n을 각각 구한다.", "자연수가 위로 막히지 않으므로 역수도 0으로 다가간다.", "1/n<0.01인 자연수 n을 하나 보이고 왜 존재하는지 한 문장으로 말한다."),
("조밀", "사이", "유리수", "임의의 두 실수 사이에는 항상 유리수가 있고 무리수도 있다.", "1과 1.5 사이에는 5/4가 있다. √2와 √2+1 사이에도 유리수가 존재한다.", "바로 이웃한 다음 실수가 있다고 가정하면 그 사이에 유리수를 넣을 수 없게 된다. 실수에는 '바로 다음 수'가 없다.", "주어진 구간 5개마다 그 안에 들어가는 유리수 하나를 분수로 찾는다.", "유리수가 조밀하다는 말은 빈틈이 없다는 뜻이 아니라, 아무리 작은 구간을 잡아도 그 안에 유리수가 들어 있다는 뜻이다.", "0과 0.1 사이의 유리수 하나를 분수로 제시하고, 왜 그 구간 안에 들어가는지 설명한다."),
("엡실론-N", "입실론", "번호", "수열이 L로 수렴한다는 것은 어떤 양수 엡실론을 줘도, 어떤 번호 N 뒤로는 항과 L의 거리가 엡실론보다 작다는 뜻이다. N은 엡실론 다음에 고른다.", "1/n은 0으로 간다. 엡실론 0.1이면 N=10 다음부터 거리가 0.1 미만이다.", "N을 먼저 정해 두고 그 다음 엡실론을 고르면 정의의 순서가 뒤집힌다.", "1/n, 1/n^2, (n+1)/n에 대해 엡실론 0.01일 때의 N을 구한다.", "N은 엡실론에 의존한다. 엡실론이 작아지면 N은 보통 커진다.", "1/n이 0으로 수렴함을 엡실론-N으로 쓰고 N을 엡실론으로 표현한다."),
("단조수렴", "증가", "유계", "증가하면서 위로 유계인 수열은 그 상한으로 수렴한다.", "1-1/n은 증가하고 1 이하이다. 상한 1로 수렴한다.", "증가만 하고 유계가 아니면 1, 2, 3, ...처럼 수렴하지 않는다. 유계를 빼먹으면 정리가 거짓이 된다.", "증가 유계 수열 3개의 극한을 상한으로 말하고, 유계가 아닌 증가 수열 하나의 반례를 적는다.", "상한보다 엡실론만큼 아래에는 집합의 점이 있으므로, 그 항 뒤의 증가 수열은 상한 근처에 갇힌다.", "1-1/n이 1로 수렴하는 이유를 단조수렴 정리의 두 가정으로 말한다."),
("축소구간", "교집합", "한 점", "닫힌구간이 앞의 구간을 포함하고 길이가 0으로 가면, 모든 구간에 공통인 점이 정확히 하나 있다.", "[0,1], [0,1/2], [0,1/4], ...의 공통점은 0뿐이다.", "열린구간 (0,1/n)은 길이가 0으로 가도 공통점이 없다. 닫힘을 빼면 정리가 깨진다.", "축소 닫힌구간 2개의 공통점을 찾고, 열린 반례 하나를 적는다.", "완비가 공통점을 보장하고, 길이가 0으로 가면 점이 둘일 수 없다.", "위 구간의 공통점이 0뿐인 이유와 열린 반례를 함께 말한다."),
("볼차노-바이어슈트라스", "부분수열", "유계", "유계인 수열은 수렴하는 부분수열을 갖는다. 증명은 축소구간으로 반을 고르는 스케치로 남긴다.", "(-1)^n은 유계이고, 짝수 항 부분수열은 1로 수렴한다.", "유계가 아닌 1, 2, 3, ...은 수렴 부분수열이 없다.", "유계 수열 3개에서 수렴 부분수열을 하나 찾고, 비유계 반례 하나를 적는다.", "무한 번 돌아가는 유계 수열은 반직선 중 한쪽에 무한히 많이 모이므로 구간을 줄여 갈 수 있다.", "(-1)^n의 수렴 부분수열을 하나 보이고 원래 수열이 수렴하지 않는 이유도 말한다.", "sketch"),
("코시 수열", "서로", "극한", "코시 수열은 번호가 충분히 크면 항끼리의 거리가 임의의 엡실론보다 작다. 실수에서는 코시 수열과 수렴 수열이 같다.", "1/n은 코시다. m, n이 둘 다 N보다 크면 |1/n-1/m|은 1/N보다 작다.", "항이 극한에 가까운 것과, 항끼리 가까운 것을 구분하지 않으면 유리수만의 세계에서 코시인데 수렴하지 않는 예를 놓친다. 제곱근 2로 가는 유리수 수열이 그 예다.", "1/n이 코시임을 보이고, 유리수 안에서 제곱근 2로 다가가는 수열이 유리수 극한을 갖지 않음을 말한다.", "실수의 완비가 코시 수열의 극한을 실수 안에 붙잡아 둔다.", "1/n이 코시인 이유와, 유리수에만 있으면 실패하는 예를 한 문장씩 말한다."),
("급수의 정의", "부분합", "수렴", "급수가 수렴한다는 것은 부분합 수열이 수렴한다는 뜻이다. 항이 0으로 가는 것만으로는 부족하다.", "등비급수 1/2+1/4+1/8+...의 부분합은 1-1/2^n이라 1로 간다.", "조화급수 1+1/2+1/3+...은 항이 0으로 가지만 부분합은 무한히 커진다.", "등비급수 3개의 부분합을 닫힌 형태로 구하고, 조화급수가 발산하는 묶음 논증을 네 줄로 쓴다.", "급수는 항이 아니라 합의 수열을 본다.", "1/2+1/4+1/8+...이 1로 수렴함을 부분합으로 보이고, 항이 0으로 가는 것만으로 부족한 급수 이름을 말한다."),
("절대수렴", "절댓값", "조건", "절댓값의 급수가 수렴하면 원래 급수도 수렴한다. 그 역은 거짓이다.", "(-1/2)^n의 절댓값 급수는 등비 1/2라 절대수렴이다.", "교대 조화급수는 수렴하지만 절댓값인 조화급수는 발산한다. 절대수렴이라고 부르면 안 된다.", "절대수렴 3개와, 수렴하지만 절대수렴이 아닌 1개를 판정한다.", "절대수렴은 순서를 바꿔도 합이 같다는 더 강한 성질의 입구다. 그 증명은 다음 비교에서 스케치한다.", "(-1/2)^n이 절대수렴인 이유와 교대 조화급수가 아닌 이유를 말한다."),
("교대급수", "부호", "감소", "부호가 바뀌고 절댓값이 0으로 감소하면 교대급수는 수렴한다.", "1-1/2+1/3-1/4+...는 교대 조화급수다. 부분합은 두 줄 사이에 끼어 수렴한다.", "절댓값이 감소하지 않으면 정리를 쓸 수 없다. 1-1+1-1은 항의 크기가 안 준다.", "교대급수 4개를 판정하고 1-1+1-1이 왜 안 되는지 적는다.", "짝수 부분합과 홀수 부분합이 서로 다가오며 사이가 항의 크기만큼이라 0으로 간다.", "교대 조화급수가 수렴하는 이유와 절대수렴이 아닌 이유를 함께 말한다."),
("완비 점검", "정의", "순서", "상한, 엡실론-N, 단조수렴, 코시를 각 한 문제씩 쓰고 정의의 순서를 지켰는지 표시한다.", "점검 예는 (0,1)의 상한, 1/n의 엡실론-N, 1-1/n의 단조수렴, 1/n의 코시다.", "N을 엡실론보다 먼저 고정한 문장이 있으면 그 문항은 다시 쓴다.", "네 문항을 백지에 쓰고 각 정의의 한정사 순서를 밑줄로 표시한다.", "해석학의 실수는 순서와 한정사를 틀리면 다른 주장이 된다.", "1/n의 수렴을 엡실론-N으로 백지에 쓰고 N이 어디에 의존하는지 말한다."),
], mode="proof")
